import {mergeGeometries} from './vendor/BufferGeometryUtils.js';
// Reusable metre-scale shapes. All static parts are merged by finish before instancing.
export function createLevel0Props(T){
 const rounded=(w,h,d,r=.025,segments=4)=>{const g=new T.BoxGeometry(w,h,d,segments,segments,segments),p=g.attributes.position,n=g.attributes.normal;for(let i=0;i<p.count;i++){const a=new T.Vector3(p.getX(i),p.getY(i),p.getZ(i)),q=new T.Vector3(T.MathUtils.clamp(a.x,-w/2+r,w/2-r),T.MathUtils.clamp(a.y,-h/2+r,h/2-r),T.MathUtils.clamp(a.z,-d/2+r,d/2-r)),v=a.clone().sub(q).normalize();a.copy(q).addScaledVector(v,r);p.setXYZ(i,a.x,a.y,a.z);n.setXYZ(i,v.x,v.y,v.z);}return g;};
 function make(fn){const pools={};const put=(m,g,x=0,y=0,z=0,rx=0,ry=0,rz=0)=>{g.rotateX(rx);g.rotateY(ry);g.rotateZ(rz);g.translate(x,y,z);(pools[m]??=[]).push(g.index?g.toNonIndexed():g);};const box=(m,x,y,z,w,h,d,r=.012,rx=0,ry=0,rz=0)=>put(m,rounded(w,h,d,Math.min(r,w*.24,h*.24,d*.24)),x,y,z,rx,ry,rz);const tube=(m,points,r=.006)=>put(m,new T.TubeGeometry(new T.CatmullRomCurve3(points.map(p=>new T.Vector3(...p))),Math.max(16,points.length*4),r,6,false));const leg=(m,x,z,height=.40,r=.024)=>{const pts=[[r*.65,0],[r*.8,.04],[r*.62,height*.28],[r*.85,height*.48],[r*.55,height*.64],[r,height*.9],[r,height]].map(p=>new T.Vector2(...p));put(m,new T.LatheGeometry(pts,10),x,0,z);};fn({put,box,tube,leg});return Object.entries(pools).map(([material,geos])=>{const geometry=mergeGeometries(geos,false);for(const g of geos)g.dispose();return{material,geometry,matrix:new T.Matrix4(),castShadow:true};});}
 const props={}; // Upholstered and cabinet furniture is owned by level0-furniture93.js.
 props.crt=make(({put,box,tube})=>{box('blackPlastic',0,.275,0,.64,.54,.56,.055);box('dark',0,.29,.27,.59,.46,.04);const g=new T.PlaneGeometry(.49,.34,20,14),p=g.attributes.position;for(let i=0;i<p.count;i++){const x=p.getX(i),y=p.getY(i);p.setZ(i,.029*(1-(x/.27)**2)*(1-(y/.19)**2));}g.computeVertexNormals();put('screen',g,0,.31,.303);for(let i=0;i<7;i++)box('dark',-.16+i*.035,.060,.295,.02,.008,.006,.001);for(const x of[.19,.235])put('steel',new T.CylinderGeometry(.016,.016,.015,12),x,.06,.305,Math.PI/2);tube('dark',[[.12,.08,-.29],[.18,.02,-.52],[.36,.006,-.64],[.52,.006,-.36]],.005);});
 props.lamp=make(({put,box})=>{put('fabric',new T.CylinderGeometry(.14,.18,.05,24),0,.025,0);put('metal',new T.CylinderGeometry(.012,.016,.41,12),0,.23,0);put('fabric',new T.CylinderGeometry(.16,.255,.30,32,1,true),0,.57,0);put('fabric',new T.TorusGeometry(.255,.007,5,32),0,.42,0,Math.PI/2);put('fabric',new T.TorusGeometry(.16,.006,5,32),0,.72,0,Math.PI/2);box('metal',0,.43,0,.006,.008,.44,.001);});
 props.lamp.forEach(part=>part.castShadow=false);
 props.bin=make(({put,box})=>{const p=[[0,0],[.225,0],[.236,.02],[.28,.57],[.286,.60],[.285,.633],[.268,.638],[.263,.61],[.256,.575],[.214,.035],[0,.035]].map(a=>new T.Vector2(...a));put('bin',new T.LatheGeometry(p,40));for(const y of[.036,.59,.63])put('bin',new T.TorusGeometry(y<.1?.237:.282,.01,6,40),0,y,0,Math.PI/2);for(const x of[-.278,.278])box('bin',x,.577,0,.028,.05,.13,.01);});
 props.pail=make(({put,tube})=>{const p=[[0,0],[.111,0],[.124,.015],[.153,.31],[.16,.323],[.151,.33],[.144,.309],[.115,.023],[0,.023]].map(a=>new T.Vector2(...a));put('pail',new T.LatheGeometry(p,36));for(const y of[.025,.313])put('metal',new T.TorusGeometry(y<.1?.12:.155,.004,5,36),0,y,0,Math.PI/2);const pts=[];for(let i=0;i<=24;i++){const a=Math.PI*i/24;pts.push([Math.cos(a)*.153,.29+Math.sin(a)*.18,0]);}tube('metal',pts,.004);put('dark',new T.CylinderGeometry(.009,.009,.065,8),0,.464,0,0,0,Math.PI/2);});
 // Solid thickness, modeled face plate, screws, recessed prong slots and ground opening.
 const outlets=[];for(let style=0;style<5;style++)outlets.push(make(({put,box})=>{const wide=style===3,w=wide?.116:.073,h=.116;box(style===3?'steel':style===1?'socketBrown':'socketIvory',0,0,.005,w,h,.010,.006);const g=new T.PlaneGeometry(w*.90,h*.968);put('outlet'+style,g,0,0,.0106);for(const x of wide?[-.025,.025]:[0])for(const y of[-.0255,.0255]){if(style===2)continue;const shape=new T.Shape();shape.moveTo(-.017,-.016);shape.lineTo(.017,-.016);shape.quadraticCurveTo(.023,-.012,.023,.003);shape.quadraticCurveTo(.020,.018,.012,.019);shape.lineTo(-.012,.019);shape.quadraticCurveTo(-.023,.013,-.023,.003);shape.quadraticCurveTo(-.023,-.012,-.017,-.016);const hole=(a,b,c,d)=>{const p=new T.Path();p.moveTo(a,b);p.lineTo(a,b+d);p.lineTo(a+c,b+d);p.lineTo(a+c,b);p.closePath();shape.holes.push(p);};hole(-.009,.002,.003,.012);hole(.006,.002,.003,.010);if(style!==4){const p=new T.Path();p.absellipse(0,-.008,.0045,.0055,0,Math.PI*2,true);shape.holes.push(p);}const geo=new T.ExtrudeGeometry(shape,{depth:.004,bevelEnabled:true,bevelSize:.0007,bevelThickness:.0007,bevelSegments:1,curveSegments:6});put(style===1?'socketBrown':'socketIvory',geo,x,y,.0115);box('dark',x,y,.011,.041,.033,.001,.0001);}
 if(style===2){box('socketWhite',0,.003,.012,.040,.073,.004,.002);for(const y of[-.024,.027])for(const x of[-.008,.008])box('dark',x,y,.015,.003,.011,.001,.0001);for(const y of[-.004,.008])box(y<0?'socketBrown':'socketWhite',0,y,.017,.022,.007,.003,.001);}
 for(const y of style===2?[-.05,.05]:[0]){put('steel',new T.CylinderGeometry(.003,.003,.0018,12),0,y,.013,Math.PI/2);box('dark',0,y,.014,.004,.00065,.001,.0001);}}));
 props.breaker=make(({put,box})=>{box('enamel',0,0,.045,.40,.60,.09,.015);box('dark',0,0,.092,.353,.543,.006,.003);put('breaker',new T.PlaneGeometry(.346,.530),0,0,.097);for(const x of[-.050,.050])for(let i=0;i<10;i++)box('blackPlastic',x,.175-i*.036,.105,.034,.026,.017,.002);for(const x of[-.186,.186])for(const y of[-.279,.279])put('steel',new T.CylinderGeometry(.006,.006,.004,8),x,y,.096,Math.PI/2);const hingeX=-.197,hingeZ=.100,angle=1.13,width=.39;box('enamel',hingeX-Math.cos(angle)*width/2,0,hingeZ+Math.sin(angle)*width/2,width,.60,.014,.004,0,angle);for(const y of[-.20,.20]){put('metal',new T.CylinderGeometry(.009,.009,.074,12),hingeX,y,hingeZ);box('enamel',hingeX+.018,y,hingeZ-.006,.036,.065,.008,.002);}});
 props.lever=make(({box})=>{box('blackPlastic',0,0,.025,.115,.026,.055,.005);box('blackPlastic',0,-.050,.047,.065,.092,.025,.005);box('steel',0,-.094,.047,.092,.025,.027,.004);});
 return{...props,outlets};
}
